describe('Freeze First Column on Horizontal Scroll', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.get('[data-testid="table-container"]').should('be.visible');
  });

  it('should keep first column visible when scrolling horizontally', () => {
    // Get initial position of first column
    cy.get('[data-testid="table-first-column"]').then(($firstCol) => {
      const initialLeft = $firstCol[0].getBoundingClientRect().left;

      // Scroll table horizontally
      cy.get('[data-testid="table-scroll-container"]').scrollTo('right', { duration: 500 });

      // Verify first column remains in same position
      cy.get('[data-testid="table-first-column"]').then(($firstColAfter) => {
        const finalLeft = $firstColAfter[0].getBoundingClientRect().left;
        expect(finalLeft).to.equal(initialLeft);
      });
    });

    // Verify other columns are scrolled
    cy.get('[data-testid="table-last-column"]').then(($lastCol) => {
      const lastColLeft = $lastCol[0].getBoundingClientRect().left;
      expect(lastColLeft).to.be.greaterThan(0);
    });
  });

  it('should maintain first column freeze position with multiple scroll actions', () => {
    const scrollPositions = [];

    // Perform multiple scroll actions
    cy.get('[data-testid="table-scroll-container"]').scrollTo('right', { duration: 300 });
    cy.get('[data-testid="table-first-column"]').then(($col) => {
      scrollPositions.push($col[0].getBoundingClientRect().left);
    });

    cy.get('[data-testid="table-scroll-container"]').scrollTo('center', { duration: 300 });
    cy.get('[data-testid="table-first-column"]').then(($col) => {
      scrollPositions.push($col[0].getBoundingClientRect().left);
    });

    cy.get('[data-testid="table-scroll-container"]').scrollTo('left', { duration: 300 });
    cy.get('[data-testid="table-first-column"]').then(($col) => {
      scrollPositions.push($col[0].getBoundingClientRect().left);
    });

    // All positions should be identical
    cy.wrap(scrollPositions).then((positions) => {
      expect(positions[0]).to.equal(positions[1]);
      expect(positions[1]).to.equal(positions[2]);
    });
  });

  it('should apply freeze styling to first column', () => {
    cy.get('[data-testid="table-first-column"]').should('have.css', 'position', 'sticky');
    cy.get('[data-testid="table-first-column"]').should('have.css', 'left', '0px');
    cy.get('[data-testid="table-first-column"]').should('have.css', 'z-index');
  });

  it('should handle edge case when table has minimal width', () => {
    cy.viewport(320, 568);
    cy.get('[data-testid="table-scroll-container"]').scrollTo('right', { duration: 500 });

    cy.get('[data-testid="table-first-column"]').should('be.visible');
    cy.get('[data-testid="table-first-column"]').then(($col) => {
      const rect = $col[0].getBoundingClientRect();
      expect(rect.left).to.be.greaterThanOrEqual(0);
      expect(rect.right).to.be.lessThanOrEqual(320);
    });
  });

  it('should preserve first column content visibility during scroll', () => {
    cy.get('[data-testid="table-first-column-cell"]').each(($cell) => {
      cy.wrap($cell).should('be.visible');
      cy.wrap($cell).should('have.text.length.greaterThan', 0);
    });

    cy.get('[data-testid="table-scroll-container"]').scrollTo('right', { duration: 500 });

    cy.get('[data-testid="table-first-column-cell"]').each(($cell) => {
      cy.wrap($cell).should('be.visible');
      cy.wrap($cell).should('have.text.length.greaterThan', 0);
    });
  });

  it('should handle edge case with very wide table content', () => {
    cy.get('[data-testid="table-scroll-container"]').then(($container) => {
      const containerWidth = $container.width();
      const scrollWidth = $container[0].scrollWidth;

      expect(scrollWidth).to.be.greaterThan(containerWidth);
    });

    cy.get('[data-testid="table-scroll-container"]').scrollTo('right', { duration: 500 });
    cy.get('[data-testid="table-first-column"]').should('be.visible');
    cy.get('[data-testid="table-first-column"]').should('have.css', 'position', 'sticky');
  });
});
